window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[270]={"id":"270","numero":270,"titre":"Douleur lombaire aiguë","objectifs":[{"id":"270-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les spécificités de l'interrogatoire et de l'examen clinique face à une douleur lombaire aiguë","contenu":"<div class=\"callout callout-info\"><strong>Enjeu.</strong> Une <span class=\"kw-clinique\">douleur lombaire aiguë</span> impose d'abord de séparer une cause <span class=\"kw-def\">rhumatologique</span> d'une cause <span class=\"kw-def\">urologique</span> (et d'éliminer une <span class=\"kw-alerte\">urgence</span>). Tout se joue à l'<strong>interrogatoire</strong> et à l'<strong>examen clinique</strong>, qui orientent ensuite le bilan.</div>\n\n      <p><strong>Interrogatoire</strong> — recueil systématique :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">ATCD</span> : lombalgies antérieures, pathologies <span class=\"kw-clinique\">neurologiques</span>, <span class=\"kw-clinique\">rhumatologiques</span> ou <span class=\"kw-clinique\">urologiques</span>, interventions chirurgicales</li>\n        <li><strong>Mode d'apparition</strong> : date, début <span class=\"kw-clinique\">brutal</span> ou <span class=\"kw-clinique\">progressif</span></li>\n        <li><strong>Contexte de survenue</strong> : <span class=\"kw-etio\">effort physique</span>, <span class=\"kw-etio\">chute</span>, au repos, après un <span class=\"kw-etio\">long trajet en voiture</span></li>\n        <li><strong>Caractéristiques de la douleur</strong> : topographie, <span class=\"kw-clinique\">irradiation</span>, <span class=\"kw-clinique\">unilatérale</span> ou bilatérale, présence ou non d'une <span class=\"kw-clinique\">position antalgique</span></li>\n        <li>Facteurs modulants : douleur accentuée par certains mouvements (<span class=\"kw-clinique\">marche</span>, <span class=\"kw-clinique\">antéflexion</span>) ou cédant dans une position</li>\n        <li>Efficacité des <span class=\"kw-ttt\">antalgiques de palier 1</span></li>\n        <li><strong>Signes associés</strong> : signes généraux (<span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">AEG</span>), urologiques (<span class=\"kw-clinique\">signes fonctionnels urinaires</span>, <span class=\"kw-clinique\">hématurie</span>), digestifs</li>\n        <li>🚩 Recherche de <span class=\"kw-alerte\">drapeaux rouges</span> : troubles neurologiques des membres inférieurs ou sphinctériens, <span class=\"kw-clinique\">fièvre</span> mal tolérée, signes de <span class=\"kw-alerte\">choc</span></li>\n      </ul>\n\n      <p><strong>Examen clinique</strong> :</p>\n      <ul>\n        <li><strong>Observation</strong> debout, à la marche, assis : une douleur d'<span class=\"kw-def\">origine urologique</span> limite par la douleur mais <span class=\"kw-clinique\">la marche n'a pas de caractère neurologique</span></li>\n        <li><span class=\"kw-clinique\">Constantes</span> : pouls, température, tension artérielle</li>\n        <li><strong>Examen du dos</strong> : cicatrices, rougeurs, <span class=\"kw-clinique\">œdèmes</span>, <span class=\"kw-clinique\">déformations rachidiennes</span> (scoliose, hyperlordose) — un épisode subaigu peut se greffer sur une pathologie chronique connue</li>\n        <li><span class=\"kw-clinique\">Palpation</span> du rachis et des groupes musculaires dorsaux</li>\n        <li><span class=\"kw-clinique\">Signe de Lasègue</span> (élévation passive du membre inférieur tendu en décubitus dorsal) si suspicion de sciatique</li>\n        <li><span class=\"kw-clinique\">Examen neurologique</span> si origine rhumatologique suspectée</li>\n        <li><span class=\"kw-clinique\">Percussion lombaire</span> (ébranlement) en cas de suspicion urologique — <strong>toujours commencer du côté non douloureux</strong></li>\n        <li>Examen <span class=\"kw-clinique\">abdominal</span> complet (inspection, palpation, percussion)</li>\n      </ul>\n\n      <div class=\"callout callout-danger\"><strong>🚩 Si rétention aiguë d'urine associée</strong>, rechercher systématiquement :\n        <ul>\n          <li><span class=\"kw-def\">Syndrome de compression médullaire</span> (notamment en regard du cône terminal) : syndrome sous-lésionnel avec troubles <span class=\"kw-clinique\">moteurs</span>, <span class=\"kw-clinique\">sensitifs</span> et <span class=\"kw-clinique\">sphinctériens</span></li>\n          <li><span class=\"kw-def\">Syndrome de la queue-de-cheval</span> : <span class=\"kw-clinique\">anesthésie en selle</span>, troubles moteurs des membres inférieurs avec troubles de la marche, <span class=\"kw-clinique\">abolition des ROT</span> des membres inférieurs, troubles <span class=\"kw-clinique\">génito-sphinctériens</span> (impuissance, <span class=\"kw-clinique\">constipation</span>, mictions impérieuses)</li>\n        </ul>\n      </div>\n\n      <p style=\"margin-top:18px\"><strong>Orientation clinique urologique <span class=\"kw-bio\">vs</span> rhumatologique</strong></p>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Origine urologique</th><th>Origine rhumatologique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Circonstances</strong></td>\n            <td>Apparition <span class=\"kw-clinique\">brutale</span> ++ ; long trajet en voiture, repas copieux, geste/<span class=\"kw-ttt\">chirurgie</span> rénal récent, traumatisme lombaire</td>\n            <td><span class=\"kw-etio\">Traumatisme</span>, <span class=\"kw-etio\">effort physique</span> récent (soulèvement ++)</td>\n          </tr>\n          <tr>\n            <td><strong>ATCD</strong></td>\n            <td>ATCD <span class=\"kw-clinique\">urologiques</span></td>\n            <td>ATCD <span class=\"kw-clinique\">rhumatologiques</span></td>\n          </tr>\n          <tr>\n            <td><strong>Siège</strong></td>\n            <td>Fosse lombaire <span class=\"kw-clinique\">unilatérale</span></td>\n            <td>Lombaire basse, lombofessière</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Irradiation</span></strong></td>\n            <td>Organes génitaux externes</td>\n            <td>Région sacrée, épines iliaques postéro-supérieures, face postérieure de la cuisse</td>\n          </tr>\n          <tr>\n            <td><strong>Signes associés</strong></td>\n            <td><span class=\"kw-clinique\">Hématurie</span>, <span class=\"kw-clinique\">iléus réflexe</span>, signes fonctionnels urinaires</td>\n            <td><span class=\"kw-alerte\">Troubles neurologiques</span> : membres inférieurs ou sphinctériens</td>\n          </tr>\n          <tr>\n            <td><strong>Inspection</strong></td>\n            <td>Cicatrices de <span class=\"kw-ttt\">chirurgie</span>, contusion</td>\n            <td>Trouble de la statique rachidienne (scoliose, hyperlordose), marche</td>\n          </tr>\n          <tr>\n            <td><strong>Palpation / percussion</strong></td>\n            <td>Percussion des fosses lombaires</td>\n            <td>Palpation rachidienne et paravertébrale, mobilité du rachis, douleurs sacro-iliaques/hanches/fessiers, <span class=\"kw-clinique\">Lasègue</span>, examen neurologique</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 94 — Rachialgie · 95 — Radiculalgie - Syndrome canalaire</em></p>","frequence":0},{"id":"270-2","rang":"A","rubrique":"Etiologies","titre":"Connaître les étiologies et les diagnostics différentiels des douleurs lombaires et les arguments en faveur d'une lombalgie commune ou secondaire","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> Par convention, une lombalgie est dite <span class=\"kw-def\">aiguë</span> lorsqu'elle évolue depuis <span class=\"kw-chiffre\">&lt; 6 semaines</span>, et <span class=\"kw-def\">chronique</span> au-delà de <span class=\"kw-chiffre\">&gt; 12 semaines</span>.</div>\n\n      <p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">douleurs lombaires</span> ont des étiologies de plusieurs grands appareils — la première démarche est d'identifier l'origine.</p>\n      <table >\n        <thead><tr><th>Origine</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Urologiques</strong></td>\n            <td>\n              <ul>\n                <li><strong>Obstructives :</strong> <span class=\"kw-etio\">calculs</span>, tumeur, compression externe des voies urinaires, <span class=\"kw-etio\">syndrome de la jonction pyélo-urétérale</span></li>\n                <li><strong>Infectieuses :</strong> <span class=\"kw-etio\">pyélonéphrite aiguë</span>, pyonéphrose, <span class=\"kw-clinique\">abcès</span> rénal</li>\n                <li><strong>Vasculaires :</strong> ischémie (<span class=\"kw-etio\">infarctus du rein</span>), hématome rénal ou périrénal</li>\n                <li><strong>Traumatisme rénal :</strong> fracture rénale, urinome, hématome</li>\n                <li><strong>Tumeur / kyste du rein</strong> (rarement douloureux en aigu, sauf saignement ou infection)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Rhumatologiques</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-def\">Lombalgie commune</span> : origine <span class=\"kw-etio\">discale</span> (fissure/arrachement de l'annulus, dégénérescence du nucleus, protrusion), <span class=\"kw-etio\">ligamentaire</span>, <span class=\"kw-etio\">musculaire</span> ou <span class=\"kw-etio\">arthrosique</span></li>\n                <li><span class=\"kw-def\">Lombalgie secondaire</span> d'origine non dégénérative (<span class=\"kw-chiffre\">&lt; 1 %</span>) : <span class=\"kw-etio\">tumorale</span> (métastases ++), <span class=\"kw-etio\">infectieuse</span> (spondylodiscite), <span class=\"kw-etio\">fracture vertébrale</span>, <span class=\"kw-etio\">spondylarthrite</span></li>\n                <li>Douleur costale (traumatisme, tumeur)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vasculaires</strong></td>\n            <td>Fissuration d'un <span class=\"kw-alerte\">anévrisme de l'aorte</span> ou de ses branches ; <span class=\"kw-alerte\">dissection aortique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Digestives</strong></td>\n            <td>Affection iléocolique (<span class=\"kw-etio\">infarctus mésentérique</span>), <span class=\"kw-etio\">pancréatite aiguë</span>, <span class=\"kw-clinique\">colique hépatique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Gynécologiques</strong></td>\n            <td><span class=\"kw-alerte\">Grossesse extra-utérine</span>, torsion de kyste ovarien</td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>Pneumopathie aiguë, hématome du psoas, hématome et tumeur surrénalienne</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"obj-callout success\" style=\"border-left:4px solid var(--spe-pneumo,#6b7a3a)\"><strong>Lombalgie commune <span class=\"kw-bio\">vs</span> secondaire</strong> <em>(à distinguer)</em>\n        <ul>\n          <li><span class=\"kw-def\">Commune</span> (dégénérative, la plus fréquente) : déclenchée par un effort, mécanique, sans <span class=\"kw-alerte\">drapeau rouge</span> — <strong>aucun examen complémentaire</strong> en <span class=\"kw-chiffre\">première intention</span></li>\n          <li><span class=\"kw-def\">Secondaire</span> (<span class=\"kw-chiffre\">&lt; 1 %</span>) : à évoquer devant des <span class=\"kw-alerte\">drapeaux rouges</span> (<span class=\"kw-clinique\">AEG</span>, fièvre, douleur nocturne/<span class=\"kw-etio\">inflammatoire</span>, déficit neurologique, ATCD néoplasique) → impose une imagerie</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 94 — Rachialgie · 95 — Radiculalgie - Syndrome canalaire</em></p>","frequence":0},{"id":"270-3","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier une urgence médicale ou chirurgicale","contenu":"<div class=\"callout callout-danger\"><strong>🚩 <span class=\"kw-alerte\">Drapeaux rouges</span> devant une douleur lombaire aiguë</strong> — imposent une prise en charge urgente :\n        <ul>\n          <li>Troubles <span class=\"kw-alerte\">neurologiques</span> des membres inférieurs ou <span class=\"kw-alerte\">sphinctériens</span></li>\n          <li><span class=\"kw-alerte\">Fièvre mal tolérée</span></li>\n          <li><span class=\"kw-alerte\">Signes de choc</span></li>\n          <li>Déglobulisation</li>\n        </ul>\n      </div>\n\n      <p><span class=\"kw-clinique\">Les</span> urgences à éliminer combinent urgences <strong>neurochirurgicales</strong>, <strong>vasculaires</strong>, <strong>urologiques</strong> et <strong>gynécologiques</strong> :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Urgence</span></th><th>À évoquer / CAT</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Compression médullaire / queue-de-cheval</strong></span></td>\n            <td>Devant une <span class=\"kw-clinique\">rétention aiguë d'urine</span> + déficit neurologique : <span class=\"kw-alerte\">syndrome de compression médullaire</span> (cône terminal) ou <span class=\"kw-alerte\">syndrome de la queue-de-cheval</span> (anesthésie en selle, troubles génito-sphinctériens) → <strong><span class=\"kw-alerte\">urgence</span> neurochirurgicale</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Urgence vasculaire</strong></span></td>\n            <td>Fissuration d'un <span class=\"kw-alerte\">anévrisme de l'aorte abdominale</span>, <span class=\"kw-alerte\">dissection aortique</span> → <span class=\"kw-alerte\">urgence</span> vitale</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Pyélonéphrite sur obstacle / anurie obstructive</strong></span></td>\n            <td>Une <span class=\"kw-etio\">pyélonéphrite obstructive</span> ou une <span class=\"kw-alerte\">anurie obstructive</span> impose un <span class=\"kw-ttt\">drainage chirurgical</span> en <span class=\"kw-alerte\">urgence</span> du ou des reins (cf. imagerie)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Colique néphrétique compliquée</strong></span></td>\n            <td><span class=\"kw-alerte\">Signes de gravité</span>, <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span>, signes de <span class=\"kw-alerte\">choc</span> → imagerie injectée en <span class=\"kw-alerte\">urgence</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Urgence gynécologique</strong></span></td>\n            <td><span class=\"kw-alerte\">Grossesse extra-utérine</span>, torsion d'annexe chez la femme en âge de procréer</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 93 — Compression médullaire non trauma</em></p>","frequence":0},{"id":"270-4","rang":"A","rubrique":"Etiologies","titre":"Connaître les signes cliniques et les examens complémentaires en faveur d'une colique néphrétique","contenu":"<div class=\"callout callout-info\"><strong>Colique néphrétique.</strong> Douleur de mise en tension brutale des cavités rénales, le plus souvent par un <span class=\"kw-etio\">calcul</span> obstructif. Tableau <span class=\"kw-clinique\">unilatéral</span>, sans signe neurologique.</div>\n\n      <p><strong>Signes cliniques en faveur</strong> :</p>\n      <ul>\n        <li>Douleur lombaire <span class=\"kw-clinique\">unilatérale</span>, d'apparition <span class=\"kw-clinique\">brutale</span></li>\n        <li><span class=\"kw-clinique\">Irradiation</span> vers <span class=\"kw-clinique\">les</span> organes génitaux externes</li>\n        <li><span class=\"kw-clinique\">Hématurie</span> : très en faveur — son <strong>absence fait quasiment écarter</strong> le diagnostic</li>\n        <li><span class=\"kw-clinique\">Iléus réflexe</span>, signes fonctionnels urinaires</li>\n        <li><strong>Absence de signe neurologique</strong> ; <span class=\"kw-clinique\">percussion lombaire</span> sensible (débuter du côté non douloureux)</li>\n      </ul>\n\n      <p><strong>Examens complémentaires en faveur</strong> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Analyse d'urine</span> (bandelette) systématique si suspicion urologique :\n          <ul>\n            <li><span class=\"kw-bio\">Hématurie</span> : très en faveur d'une colique néphrétique</li>\n            <li><span class=\"kw-bio\">Leucocyturie</span> → <span class=\"kw-bio\">ECBU</span> à la recherche d'une infection</li>\n          </ul>\n        </li>\n        <li><strong>Imagerie</strong> si colique néphrétique typique non compliquée :\n          <ul>\n            <li><span class=\"kw-imagerie\">TDM abdomino-pelvienne non injectée</span></li>\n            <li>ou <span class=\"kw-imagerie\">échographie</span> + <span class=\"kw-imagerie\">ASP</span> (cliché de l'arbre urinaire) — dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 48 h</span></li>\n          </ul>\n        </li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 265 — Lithiase urinaire</em></p>","frequence":0},{"id":"270-5","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l'indication des examens d'imagerie devant une douleur lombaire aiguë de l'adulte","contenu":"<p>L'imagerie est <strong>guidée par l'orientation clinique</strong> (rhumatologique <span class=\"kw-bio\">vs</span> urologique) et par la présence de <span class=\"kw-alerte\">signes de gravité</span>.</p>\n\n      <p><strong>Orientation rhumatologique</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Lombalgie commune</span> : <strong>aucun examen d'imagerie</strong> n'est requis</li>\n        <li><span class=\"kw-imagerie\">Radiographies standards</span> puis <span class=\"kw-imagerie\">IRM du rachis lombaire</span> justifiées si :\n          <ul>\n            <li>Douleurs rebelles au traitement symptomatique, évoluant vers l'<span class=\"kw-alerte\">aggravation</span></li>\n            <li>Suspicion de <span class=\"kw-def\">lombalgie secondaire</span> d'origine non dégénérative</li>\n          </ul>\n        </li>\n      </ul>\n\n      <p><strong>Orientation urologique</strong></p>\n      <table >\n        <thead><tr><th>Situation</th><th>Imagerie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Colique néphrétique <strong>typique non compliquée</strong></td>\n            <td><span class=\"kw-imagerie\">TDM-AP non injectée</span> ou <span class=\"kw-imagerie\">échographie</span> + <span class=\"kw-imagerie\">ASP</span> (<span class=\"kw-chiffre\">&lt; 48 h</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Signes de gravité</span>, <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span>, signes de <span class=\"kw-alerte\">choc</span>, déglobulisation, patient fragile ou contexte postopératoire</td>\n            <td><span class=\"kw-imagerie\">Scanner abdomino-pelvien injecté</span> <strong>en <span class=\"kw-alerte\">urgence</span></strong> (si la fonction rénale le permet)</td>\n          </tr>\n          <tr>\n            <td><strong>Doute diagnostique</strong> (autres situations)</td>\n            <td><span class=\"kw-imagerie\">Scanner abdomino-pelvien injecté</span> discuté</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Pyélonéphrite sur obstacle</span> / <span class=\"kw-alerte\">anurie obstructive</span></td>\n            <td><span class=\"kw-imagerie\">Échographie rénale</span> : une <span class=\"kw-imagerie\">hydronéphrose</span> suffit à poser l'indication d'un <span class=\"kw-ttt\">drainage chirurgical</span></td>\n          </tr>\n          <tr>\n            <td>Suspicion de <span class=\"kw-def\">spondylodiscite</span></td>\n            <td><span class=\"kw-imagerie\">IRM</span> (examen de référence du diagnostic)</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"270-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître le bilan biologique à prescrire en cas de douleur lombaire aiguë","contenu":"<div class=\"callout callout-info\"><strong><span class=\"kw-bio\">Bilan biologique</span> de débrouillage</strong> — communément réalisé devant une <span class=\"kw-clinique\">douleur lombaire aiguë</span> évoquant une cause <span class=\"kw-def\">urologique</span> ou un <span class=\"kw-clinique\">retentissement systémique</span>.</div>\n      <ul>\n        <li><span class=\"kw-bio\">NFS</span></li>\n        <li><span class=\"kw-bio\">CRP</span></li>\n        <li><span class=\"kw-bio\">Ionogramme</span> sanguin</li>\n        <li><span class=\"kw-bio\">Créatininémie</span> — évaluation de la <span class=\"kw-bio\">fonction rénale</span>, notamment avant <span class=\"kw-imagerie\">injection de produit de contraste</span></li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-bio\">Analyse d'urine</span> systématique</strong> si l'on suspecte une <span class=\"kw-def\">origine urologique</span> :\n        <ul>\n          <li><span class=\"kw-bio\">Leucocyturie</span> → <span class=\"kw-bio\">ECBU</span> à la recherche d'une <span class=\"kw-etio\">infection</span></li>\n          <li><span class=\"kw-bio\">Hématurie</span> → très en faveur d'une <span class=\"kw-def\">colique néphrétique</span> ; son absence fait quasiment écarter le diagnostic</li>\n        </ul>\n      </div>","frequence":0},{"id":"270-7","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les facteurs de risque de chronicisation et de passage vers la lombalgie chronique","contenu":"<p>Le risque de <span class=\"kw-def\">chronicisation</span> — passage vers la <span class=\"kw-def\">lombalgie chronique</span> — dépend de l'origine de la douleur.</p>\n\n      <div class=\"callout callout-info\" style=\"border-left:4px solid var(--spe-rhumato,#a85a3a)\"><strong>Douleur <span class=\"kw-clinique\">rhumatologique</span></strong>\n        <ul>\n          <li>La prise en charge devient complexe si l'<span class=\"kw-clinique\">évolution</span> dépasse <span class=\"kw-chiffre\">6 mois</span></li>\n          <li>Dépister <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">facteurs de risque de chronicisation</span> : <span class=\"kw-etio\">contexte psychosocial défavorable</span>, <span class=\"kw-etio\">mal-être au travail</span>, <span class=\"kw-etio\">syndrome dépressif</span></li>\n          <li>Le <span class=\"kw-ttt\">maintien d'une activité physique régulière</span> est indiqué pour limiter le risque de <span class=\"kw-clinique\">récidive</span> de <span class=\"kw-def\">lombalgie</span></li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\"><strong>Douleur <span class=\"kw-clinique\">urologique</span></strong>\n        <ul>\n          <li>Risque de <span class=\"kw-clinique\">chronicisation</span> <strong>rare</strong></li>\n          <li>Possible notamment dans un contexte de <span class=\"kw-def\">syndrome de la jonction pyélo-urétérale</span></li>\n        </ul>\n      </div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Enjeu :</strong> toute <span class=\"kw-clinique\">douleur lombaire aiguë</span> impose d'abord d'<span class=\"kw-alerte\">identifier une urgence médicale ou chirurgicale</span> avant d'étiqueter une <span class=\"kw-etio\">lombalgie commune</span>.<br><strong>1er geste :</strong> <span class=\"kw-clinique\">interrogatoire</span> + <span class=\"kw-clinique\">examen clinique</span> + prise des <span class=\"kw-clinique\">constantes</span> (pouls, température, TA) + <span class=\"kw-bio\">analyse d'urine</span> systématique.<br><strong>Délais :</strong> <span class=\"kw-imagerie\">échographie + ASP</span> ou <span class=\"kw-imagerie\">TDM non injectée</span> sous <span class=\"kw-chiffre\">48 h</span> pour une colique néphrétique typique ; <span class=\"kw-imagerie\">scanner injecté</span> et <span class=\"kw-ttt\">drainage chirurgical</span> en <span class=\"kw-alerte\">urgence</span> si obstacle infecté.</p>","hospit":"<p><strong>Sans gravité :</strong> <span class=\"kw-etio\">lombalgie commune</span> (aucun examen) et <span class=\"kw-etio\">colique néphrétique typique non compliquée</span> relèvent d'un <span class=\"kw-ttt\">traitement symptomatique</span>.<br><strong><span class=\"kw-alerte\">Urgence</span> chirurgicale (urologie) :</strong> <span class=\"kw-etio\">pyélonéphrite sur obstacle</span> ou <span class=\"kw-etio\">anurie obstructive</span> → <span class=\"kw-ttt\">drainage chirurgical</span> du ou des reins.<br><strong>Urgence vitale :</strong> <span class=\"kw-alerte\">syndrome de la queue-de-cheval</span>, <span class=\"kw-alerte\">compression médullaire</span>, <span class=\"kw-alerte\">fissuration d'anévrisme de l'aorte</span> ou <span class=\"kw-alerte\">dissection aortique</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Troubles neurologiques</span> des membres inférieurs ou <span class=\"kw-alerte\">troubles sphinctériens</span></li><li><span class=\"kw-alerte\">Fièvre mal tolérée</span></li><li><span class=\"kw-alerte\">Signes de choc</span></li><li>Si <span class=\"kw-clinique\">rétention aiguë d'urine</span> associée, rechercher systématiquement un <span class=\"kw-alerte\">syndrome de la queue-de-cheval</span> (<span class=\"kw-clinique\">anesthésie en selle</span>, <span class=\"kw-clinique\">troubles génito-sphinctériens</span>, <span class=\"kw-clinique\">abolition des ROT</span> des membres inférieurs, troubles de la marche) ou une <span class=\"kw-alerte\">compression médullaire</span> (cône terminal)</li><li><span class=\"kw-bio\">Déglobulisation</span> ou <span class=\"kw-clinique\">syndrome infectieux</span> → impose un <span class=\"kw-imagerie\">scanner abdomino-pelvien injecté</span> en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-def\">Terrain</span> : patient <span class=\"kw-clinique\">fragile</span> ou contexte <span class=\"kw-clinique\">postopératoire</span></li></ul>","principes":"<p>La démarche est avant tout <span class=\"kw-clinique\">diagnostique</span> : orienter entre une cause <span class=\"kw-etio\">urologique</span> et une cause <span class=\"kw-etio\">rhumatologique</span>, puis adapter bilan et traitement.</p><p><strong>Bilan <span class=\"kw-ttt\">biologique</span></strong></p><ul><li><span class=\"kw-bio\">Analyse d'urine</span> systématique si origine urologique suspectée : <span class=\"kw-bio\">leucocyturie</span> → <span class=\"kw-bio\">ECBU</span> ; <span class=\"kw-bio\">hématurie</span> très en faveur d'une <span class=\"kw-etio\">colique néphrétique</span>, son absence l'écarte quasiment</li><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatininémie</span> communément réalisés</li></ul><p><strong>Imagerie selon le contexte</strong></p><p>Doute diagnostique : <span class=\"kw-imagerie\">scanner abdomino-pelvien injecté</span> discuté</p><ul><li><span class=\"kw-etio\">Colique néphrétique typique non compliquée</span> : <span class=\"kw-imagerie\">TDM-AP non injectée</span> ou <span class=\"kw-imagerie\">échographie + ASP</span> (< <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">48 h</span></span>)</li><li><span class=\"kw-alerte\">Signes de gravité</span>, <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span>, <span class=\"kw-alerte\">choc</span>, <span class=\"kw-bio\">déglobulisation</span>, <span class=\"kw-def\">terrain</span> fragile ou postopératoire : <span class=\"kw-imagerie\">scanner abdomino-pelvien injecté</span> en <span class=\"kw-alerte\">urgence</span> (si la fonction rénale le permet)</li><li><span class=\"kw-etio\">Pyélonéphrite sur obstacle</span> / <span class=\"kw-etio\">anurie obstructive</span> : <span class=\"kw-imagerie\">échographie rénale</span> objectivant une <span class=\"kw-radio\">hydronéphrose</span> suffit à poser l'indication du <span class=\"kw-ttt\">drainage</span></li><li>Suspicion de <span class=\"kw-etio\">spondylodiscite</span> : <span class=\"kw-imagerie\">IRM</span></li></ul><p><strong>Lombalgie commune (rhumatologique)</strong></p><ul><li><span class=\"kw-imagerie\">Aucun examen complémentaire</span> requis</li><li><span class=\"kw-ttt\">Traitement symptomatique</span> par <span class=\"kw-ttt\">antalgiques de palier 1</span></li><li><span class=\"kw-imagerie\">Radiographies standards</span> puis <span class=\"kw-imagerie\">IRM du rachis lombaire</span> si douleurs rebelles au traitement évoluant vers l'aggravation ou <span class=\"kw-etio\">lombalgie secondaire</span> d'origine non dégénérative</li></ul>","suivi":"<p><strong>Lombalgie rhumatologique :</strong> risque de <span class=\"kw-etio\">chronicisation</span>, prise en charge complexe si l'<span class=\"kw-clinique\">évolution</span> dépasse <span class=\"kw-chiffre\">6 mois</span> ; dépister <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">facteurs de risque de chronicisation</span> (contexte psychosocial défavorable, mal-être au travail, syndrome dépressif) ; <span class=\"kw-ttt\">maintien d'une activité physique régulière</span> pour limiter les récidives.<br><strong>Lombalgie urologique :</strong> chronicisation <span class=\"kw-chiffre\">rare</span>, mais possible dans un contexte de <span class=\"kw-etio\">syndrome de la jonction pyélo-urétérale</span>.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Douleur lombaire aiguë — Durée < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>6</span> semaines</span> · interrogatoire + examen clinique + constantes (pouls, T°, TA) + analyse d'urine systématique","detail":"<h4>CAT — Douleur lombaire aiguë — Orientation devant une lombalgie aiguë (durée < 6 semaines)</h4>","branches":[{"to":"q-redflags","label":"Évaluation initiale","color":"blue"}]},{"id":"q-redflags","kind":"decision","label":"Drapeaux rouges / signes de gravité ? — Troubles neuro des MI ou sphinctériens · fièvre mal tolérée · signes de choc · rétention aiguë d'urine","branches":[{"to":"t-urgence","label":"Oui — drapeau rouge présent","color":"red"},{"to":"q-orientation","label":"Non","color":"green"}]},{"id":"t-urgence","kind":"terminal","label":"Urgence médico-chirurgicale","color":"red","detail":"<h4>Clinique</h4><ul><li>Si <span class=\"kw-clinique\">rétention aiguë d'urine</span> : rechercher un <span class=\"kw-alerte\">syndrome de la queue-de-cheval</span> (<span class=\"kw-clinique\">anesthésie en selle</span>, <span class=\"kw-clinique\">troubles génito-sphinctériens</span>, <span class=\"kw-clinique\">abolition des ROT</span> des MI) ou une <span class=\"kw-alerte\">compression médullaire</span> (cône terminal)</li><li><span class=\"kw-alerte\">Signes de choc</span> + douleur : évoquer une <span class=\"kw-etio\">fissuration d'anévrisme de l'aorte</span> ou une <span class=\"kw-etio\">dissection aortique</span></li><li><span class=\"kw-clinique\">Fièvre mal tolérée</span> / <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span> : <span class=\"kw-etio\">pyélonéphrite</span>, <span class=\"kw-etio\">spondylodiscite</span>, <span class=\"kw-etio\">abcès rénal</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Scanner abdomino-pelvien injecté</span> en <span class=\"kw-alerte\">urgence</span> si <span class=\"kw-alerte\">signes de gravité</span>, <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span>, <span class=\"kw-alerte\">choc</span>, <span class=\"kw-bio\">déglobulisation</span>, patient fragile ou contexte postopératoire (si la fonction rénale le permet)</li><li><span class=\"kw-imagerie\">Échographie rénale</span> objectivant une <span class=\"kw-radio\">hydronéphrose</span> si <span class=\"kw-clinique\">pyélonéphrite</span> sur obstacle / anurie obstructive</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Drainage chirurgical</span> du ou des reins en <span class=\"kw-alerte\">urgence</span> en cas de <span class=\"kw-etio\">pyélonéphrite sur obstacle</span> ou d'<span class=\"kw-etio\">anurie obstructive</span></li></ul>"},{"id":"q-orientation","kind":"decision","label":"Origine urologique ou rhumatologique ? — Uro : douleur unilatérale, SFU, hématurie, percussion lombaire · Rhumato : effort/traumatisme, irradiation MI, Lasègue, troubles de la statique","branches":[{"to":"t-uro","label":"Profil urologique","color":"amber"},{"to":"t-rhumato","label":"Profil rhumatologique","color":"green"}]},{"id":"t-uro","kind":"terminal","label":"Colique néphrétique typique non compliquée","color":"amber","detail":"<h4>Clinique</h4><ul><li>Douleur de la <span class=\"kw-clinique\">fosse lombaire unilatérale</span>, <span class=\"kw-clinique\">irradiation</span> vers <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">organes génitaux externes</span>, <span class=\"kw-clinique\">iléus réflexe</span>, signes fonctionnels urinaires, sans signe neurologique</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hématurie</span> très en faveur ; son absence fait quasiment écarter le diagnostic (<span class=\"kw-bio\">leucocyturie</span> → <span class=\"kw-bio\">ECBU</span> si suspicion d'infection)</li><li><span class=\"kw-imagerie\">TDM abdomino-pelvienne non injectée</span> ou <span class=\"kw-imagerie\">échographie + ASP</span> (< <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">48 h</span></span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-imagerie\">Scanner abdomino-pelvien injecté</span> en <span class=\"kw-alerte\">urgence</span> si apparition de <span class=\"kw-alerte\">signes de gravité</span>, d'infection ou de <span class=\"kw-alerte\">choc</span></li></ul>"},{"id":"t-rhumato","kind":"terminal","label":"Lombalgie commune","color":"green","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Aucun examen complémentaire</span> n'est requis</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Traitement symptomatique</span> par <span class=\"kw-ttt\">antalgiques de palier 1</span></li><li><span class=\"kw-ttt\">Maintien d'une activité physique régulière</span> pour limiter le risque de récidive</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-imagerie\">Radiographies standards</span> puis <span class=\"kw-imagerie\">IRM du rachis lombaire</span> si douleurs rebelles évoluant vers l'aggravation ou suspicion de <span class=\"kw-etio\">lombalgie secondaire</span> (<span class=\"kw-etio\">métastases</span>, <span class=\"kw-etio\">spondylodiscite</span>, <span class=\"kw-etio\">fracture vertébrale</span>, <span class=\"kw-etio\">spondylarthrite</span>)</li><li>Dépister <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">facteurs de risque de chronicisation</span> (contexte psychosocial défavorable, mal-être au travail, syndrome dépressif) — passage vers la chronicité si > <span class=\"kw-chiffre\">12 semaines</span></li></ul>"}]},"cards":[{"i":"1d6591eace65","n":270,"o":"270-1","u":"Diagnostic positif","t":"Connaître les spécificités de l'interrogatoire et de l'examen clinique face à une douleur lombaire aiguë","q":"Quels sont les éléments clés de l'interrogatoire à évaluer concernant la douleur lombaire aiguë elle-même ?","a":"<p>Concernant la douleur lombaire aiguë, les éléments clés à évaluer sont :</p><ul><li>Le <strong>mode d'apparition</strong> (date, début brutal ou progressif) et le <strong>contexte de survenue</strong> (effort physique, chute, repos, après long trajet en voiture).</li><li>Les <strong>caractéristiques de la douleur</strong> : topographie, <strong>irradiation</strong>, unilatérale ou bilatérale, présence ou non d'une <strong>position antalgique</strong>.</li><li>Les <strong>facteurs modulants</strong> : douleur accentuée par certains mouvements (marche, antéflexion) ou cédant dans une position.</li><li>L'<strong>efficacité des antalgiques de palier 1</strong>.</li><li>Les <strong>signes associés</strong> : signes généraux (fièvre, AEG), urologiques (signes fonctionnels urinaires, hématurie), digestifs.</li></ul>"},{"i":"4237e01eec23","n":270,"o":"270-1","u":"Diagnostic positif","t":"Connaître les spécificités de l'interrogatoire et de l'examen clinique face à une douleur lombaire aiguë","q":"Quels syndromes neurologiques graves doivent être recherchés en cas de rétention aiguë d'urine associée à une douleur lombaire aiguë ?","a":"<p>En cas de <strong>rétention aiguë d'urine</strong> associée, il faut systématiquement rechercher :</p><ul><li>Le <strong>syndrome de compression médullaire</strong> (notamment en regard du cône terminal) : caractérisé par un <strong>syndrome sous-lésionnel</strong> avec des <strong>troubles moteurs, sensitifs et sphinctériens</strong>.</li><li>Le <strong>syndrome de la queue-de-cheval</strong> : se manifestant par une <strong>anesthésie en selle</strong>, des <strong>troubles moteurs des membres inférieurs</strong> avec troubles de la marche, une <strong>abolition des ROT</strong> des membres inférieurs, et des <strong>troubles génito-sphinctériens</strong> (impuissance, constipation, mictions impérieuses).</li></ul>"},{"i":"4af2b4b29415","n":270,"o":"270-1","u":"Diagnostic positif","t":"Connaître les spécificités de l'interrogatoire et de l'examen clinique face à une douleur lombaire aiguë","q":"Quels sont les principaux éléments à rechercher lors de l'examen clinique général face à une douleur lombaire aiguë ?","a":"<p>Lors de l'examen clinique général, il faut rechercher :</p><ul><li>L'<strong>observation</strong> debout, à la marche, et assis.</li><li>Les <strong>constantes</strong> : pouls, température, tension artérielle.</li><li>L'<strong>examen du dos</strong> : cicatrices, rougeurs, œdèmes, déformations rachidiennes (scoliose, hyperlordose).</li><li>La <strong>palpation du rachis et des groupes musculaires dorsaux</strong>.</li><li>Le <strong>signe de Lasègue</strong> si suspicion de sciatique.</li><li>L'<strong>examen neurologique</strong> si une origine rhumatologique est suspectée.</li><li>La <strong>percussion lombaire</strong> (ébranlement) en cas de suspicion urologique, en commençant par le côté non douloureux.</li><li>Un <strong>examen abdominal complet</strong> (inspection, palpation, percussion).</li></ul>"},{"i":"af395244a4f2","n":270,"o":"270-1","u":"Diagnostic positif","t":"Connaître les spécificités de l'interrogatoire et de l'examen clinique face à une douleur lombaire aiguë","q":"Quels signes d'alerte (drapeaux rouges) doivent être recherchés à l'interrogatoire face à une douleur lombaire aiguë ?","a":"<p>Les signes d'alerte (<strong>drapeaux rouges</strong>) à rechercher impérativement sont :</p><ul><li>Des <strong>troubles neurologiques des membres inférieurs ou sphinctériens</strong>.</li><li>Une <strong>fièvre mal tolérée</strong>.</li><li>Des <strong>signes de choc</strong>.</li></ul>"},{"i":"f9691e88d63c","n":270,"o":"270-1","u":"Diagnostic positif","t":"Connaître les spécificités de l'interrogatoire et de l'examen clinique face à une douleur lombaire aiguë","q":"Quels antécédents sont à recueillir systématiquement face à une douleur lombaire aiguë ?","a":"<p>Face à une douleur lombaire aiguë, il convient de recueillir systématiquement les antécédents de :</p><ul><li><strong>Lombalgies antérieures</strong></li><li><strong>Pathologies neurologiques, rhumatologiques</strong> ou <strong>urologiques</strong></li><li><strong>Interventions chirurgicales</strong></li></ul>"},{"i":"2f981480045f","n":270,"o":"270-2","u":"Etiologies","t":"Connaître les étiologies et les diagnostics différentiels des douleurs lombaires et les arguments en faveur d'une lombalgie commune ou secondaire","q":"Quels sont les arguments en faveur d'une lombalgie commune par rapport à une lombalgie secondaire ?","a":"<ul><li>La <strong>lombalgie commune</strong> (dégénérative, la plus fréquente) est déclenchée par un effort, est de type mécanique et ne présente <strong>pas de drapeaux rouges</strong>. Elle ne nécessite aucun examen complémentaire en première intention.</li><li>La <strong>lombalgie secondaire</strong> (moins de 1%) est évoquée devant des <strong>drapeaux rouges</strong> (AEG, fièvre, douleur nocturne/inflammatoire, déficit neurologique, antécédents néoplasiques) et impose une imagerie.</li></ul>"},{"i":"30836add7e21","n":270,"o":"270-2","u":"Etiologies","t":"Connaître les étiologies et les diagnostics différentiels des douleurs lombaires et les arguments en faveur d'une lombalgie commune ou secondaire","q":"Citez les étiologies vasculaires, digestives et gynécologiques des douleurs lombaires aiguës.","a":"<ul><li><strong>Vasculaires</strong> : fissuration d'un <strong>anévrisme de l'aorte</strong> ou de ses branches, dissection aortique.</li><li><strong>Digestives</strong> : affection iléocolique (infarctus mésentérique), pancréatite aiguë, colique hépatique.</li><li><strong>Gynécologiques</strong> : <strong>grossesse extra-utérine</strong>, torsion de kyste ovarien.</li></ul>"},{"i":"5b06e5a71d57","n":270,"o":"270-2","u":"Etiologies","t":"Connaître les étiologies et les diagnostics différentiels des douleurs lombaires et les arguments en faveur d'une lombalgie commune ou secondaire","q":"Comment définit-on une lombalgie aiguë ?","a":"<p>Par convention, une lombalgie est dite aiguë lorsqu'elle évolue depuis <strong>moins de 6 semaines</strong>.</p>"},{"i":"caca21702b47","n":270,"o":"270-2","u":"Etiologies","t":"Connaître les étiologies et les diagnostics différentiels des douleurs lombaires et les arguments en faveur d'une lombalgie commune ou secondaire","q":"Quelles sont les étiologies rhumatologiques de la douleur lombaire aiguë ?","a":"<ul><li><strong>Lombalgie commune</strong> : origine discale (fissure/arrachement de l'annulus, dégénérescence du nucleus, protrusion), ligamentaire, musculaire ou arthrosique.</li><li><strong>Lombalgie secondaire d'origine non dégénérative (moins de 1%)</strong> : tumorale (<strong>métastases ++</strong>), infectieuse (spondylodiscite), fracture vertébrale, spondylarthrite.</li><li><strong>Douleur costale</strong> (traumatisme, tumeur).</li></ul>"},{"i":"ec4dd8e12dac","n":270,"o":"270-2","u":"Etiologies","t":"Connaître les étiologies et les diagnostics différentiels des douleurs lombaires et les arguments en faveur d'une lombalgie commune ou secondaire","q":"Quelles sont les étiologies urologiques de la douleur lombaire aiguë ?","a":"<ul><li><strong>Obstructives</strong> : calculs, tumeur, compression externe des voies urinaires, syndrome de la jonction pyélo-urétérale.</li><li><strong>Infectieuses</strong> : pyélonéphrite aiguë, pyonéphrose, abcès rénal.</li><li><strong>Vasculaires</strong> : ischémie (infarctus du rein), hématome rénal ou périrénal.</li><li><strong>Traumatisme rénal</strong> : fracture rénale, urinome, hématome.</li><li><strong>Tumeur / kyste du rein</strong> (rarement douloureux en aigu, sauf saignement ou infection).</li></ul>"},{"i":"11b3194a2528","n":270,"o":"270-3","u":"Identifier une urgence","t":"Identifier une urgence médicale ou chirurgicale","q":"Quelle urgence neurochirurgicale doit être évoquée devant une douleur lombaire aiguë associée à des troubles neurologiques ?","a":"Devant une douleur lombaire aiguë associée à une <strong>rétention aiguë d'urine</strong> et un <strong>déficit neurologique</strong>, il faut évoquer une <strong>compression médullaire</strong> (cône terminal) ou un <strong>syndrome de la queue-de-cheval</strong> (anesthésie en selle, troubles génito-sphinctériens). Il s'agit alors d'une <strong>urgence neurochirurgicale</strong>."},{"i":"236b64a09611","n":270,"o":"270-3","u":"Identifier une urgence","t":"Identifier une urgence médicale ou chirurgicale","q":"Quand une pyélonéphrite ou une anurie obstructive relève-t-elle d'une prise en charge urgente ?","a":"Une <strong>pyélonéphrite obstructive</strong> ou une <strong>anurie obstructive</strong> impose un <strong>drainage chirurgical en urgence</strong> du ou des reins."},{"i":"383280656895","n":270,"o":"270-3","u":"Identifier une urgence","t":"Identifier une urgence médicale ou chirurgicale","q":"Quelles urgences gynécologiques doivent être éliminées devant une douleur lombaire aiguë chez la femme en âge de procréer ?","a":"Chez la femme en âge de procréer, il faut éliminer une <strong>grossesse extra-utérine</strong> ou une <strong>torsion d'annexe</strong> devant une douleur lombaire aiguë."},{"i":"5b2cda8085ee","n":270,"o":"270-3","u":"Identifier une urgence","t":"Identifier une urgence médicale ou chirurgicale","q":"Quand une colique néphrétique devient-elle une urgence nécessitant une prise en charge particulière ?","a":"Une colique néphrétique devient une urgence et nécessite une <strong>imagerie injectée en urgence</strong> lorsqu'elle présente des <strong>signes de gravité</strong>, un <strong>syndrome infectieux</strong> ou des <strong>signes de choc</strong>."},{"i":"a0b6f5d6d020","n":270,"o":"270-3","u":"Identifier une urgence","t":"Identifier une urgence médicale ou chirurgicale","q":"Quelles urgences vasculaires doivent être éliminées devant une douleur lombaire aiguë ?","a":"Les urgences vasculaires à éliminer devant une douleur lombaire aiguë, qui sont des urgences vitales, sont la <strong>fissuration d'un anévrisme de l'aorte abdominale</strong> et la <strong>dissection aortique</strong>."},{"i":"a84be70fb3f0","n":270,"o":"270-3","u":"Identifier une urgence","t":"Identifier une urgence médicale ou chirurgicale","q":"Quels sont les drapeaux rouges devant une douleur lombaire aiguë imposant une prise en charge urgente ?","a":"Les drapeaux rouges devant une douleur lombaire aiguë sont :\n<ul>\n<li><strong>Troubles neurologiques des membres inférieurs ou sphinctériens</strong></li>\n<li><strong>Fièvre mal tolérée</strong></li>\n<li><strong>Signes de choc</strong></li>\n<li><strong>Déglobulisation</strong></li>\n</ul>"},{"i":"4924cec4b38f","n":270,"o":"270-4","u":"Etiologies","t":"Connaître les signes cliniques et les examens complémentaires en faveur d'une colique néphrétique","q":"Quels examens complémentaires simples orientent vers le diagnostic de colique néphrétique ?","a":"<ul><li><strong>Analyse d'urine</strong> (bandelette urinaire) : la présence d'une <strong>hématurie</strong> est un signe très en faveur. Une leucocyturie doit faire rechercher une infection urinaire associée via un ECBU.</li></ul>"},{"i":"4b852dca6c32","n":270,"o":"270-4","u":"Etiologies","t":"Connaître les signes cliniques et les examens complémentaires en faveur d'une colique néphrétique","q":"Quelle est la définition physiopathologique de la colique néphrétique et sa présentation clinique initiale typique ?","a":"<p>La colique néphrétique correspond à une douleur de <strong>mise en tension brutale des cavités rénales</strong>, le plus souvent due à un <strong>calcul obstructif</strong>. Cliniquement, elle se présente sous la forme d'un tableau douloureux <strong>unilatéral</strong>, d'apparition brutale, et sans signe neurologique.</p>"},{"i":"c03762aa4d71","n":270,"o":"270-4","u":"Etiologies","t":"Connaître les signes cliniques et les examens complémentaires en faveur d'une colique néphrétique","q":"Quelle est l'imagerie de première intention en cas de colique néphrétique typique et non compliquée ?","a":"<p>L'imagerie de première intention est une <strong>TDM abdomino-pelvienne non injectée</strong> ou, à défaut, une <strong>échographie</strong> couplée à un ASP. Ces examens doivent être réalisés dans les <strong>48 heures</strong>.</p>"},{"i":"ec7348a1f300","n":270,"o":"270-4","u":"Etiologies","t":"Connaître les signes cliniques et les examens complémentaires en faveur d'une colique néphrétique","q":"Quels sont les signes cliniques orientant vers une colique néphrétique typique ?","a":"<ul><li><strong>Douleur lombaire unilatérale</strong>, d'apparition brutale.</li><li>Irradiation de la douleur vers les <strong>organes génitaux externes</strong>.</li><li><strong>Hématurie</strong> : sa présence est un signe <strong>très en faveur</strong>, son absence fait quasiment écarter le diagnostic.</li><li>Possibles signes fonctionnels urinaires ou un <strong>iléus réflexe</strong>.</li><li>Absence de signe neurologique.</li><li><strong>Percussion lombaire sensible</strong> du côté atteint (à débuter du côté non douloureux).</li></ul>"},{"i":"119367882fdf","n":270,"o":"270-5","u":"Examens complémentaires","t":"Connaître l'indication des examens d'imagerie devant une douleur lombaire aiguë de l'adulte","q":"Quelle est l'indication des examens d'imagerie devant une lombalgie aiguë commune de l'adulte ?","a":"<p>Devant une lombalgie aiguë commune, <strong>aucun examen d'imagerie n'est requis</strong>.</p>"},{"i":"5b51485d312b","n":270,"o":"270-5","u":"Examens complémentaires","t":"Connaître l'indication des examens d'imagerie devant une douleur lombaire aiguë de l'adulte","q":"Quand réalise-t-on un scanner abdomino-pelvien injecté en urgence pour une colique néphrétique ?","a":"<p>Un scanner abdomino-pelvien injecté en urgence est indiqué en cas de <strong>signes de gravité</strong>, de <strong>syndrome infectieux</strong>, de <strong>signes de choc</strong>, de <strong>déglobulisation</strong>, chez un <strong>patient fragile</strong>, ou dans un <strong>contexte postopératoire</strong>, à condition que la fonction rénale le permette.</p>"},{"i":"d0e009bfd07c","n":270,"o":"270-5","u":"Examens complémentaires","t":"Connaître l'indication des examens d'imagerie devant une douleur lombaire aiguë de l'adulte","q":"Quel examen d'imagerie est indiqué en première intention pour une colique néphrétique typique non compliquée ?","a":"<p>Pour une colique néphrétique typique non compliquée, l'examen indiqué est un <strong>TDM-AP non injecté</strong> ou une <strong>échographie rénale complétée par un ASP</strong>, dans les <strong>48 heures</strong>.</p>"},{"i":"e41e87c7faab","n":270,"o":"270-5","u":"Examens complémentaires","t":"Connaître l'indication des examens d'imagerie devant une douleur lombaire aiguë de l'adulte","q":"Quel examen d'imagerie est indiqué en cas de suspicion de pyélonéphrite sur obstacle ou d'anurie obstructive et que montre-t-il ?","a":"<p>Il convient de réaliser une <strong>échographie rénale</strong>. La seule présence d'une <strong>hydronéphrose</strong> suffit à poser l'indication d'un drainage chirurgical.</p>"},{"i":"eef8a7dcaab8","n":270,"o":"270-5","u":"Examens complémentaires","t":"Connaître l'indication des examens d'imagerie devant une douleur lombaire aiguë de l'adulte","q":"Dans quels cas doit-on réaliser des radiographies standards puis une IRM du rachis lombaire face à une lombalgie aiguë ?","a":"<ul><li>Si des douleurs sont <strong>rebelles au traitement symptomatique</strong> et évoluent vers l'aggravation.</li><li>En cas de <strong>suspicion de lombalgie secondaire d'origine non dégénérative</strong>.</li></ul>"},{"i":"f9cb3d12b62d","n":270,"o":"270-5","u":"Examens complémentaires","t":"Connaître l'indication des examens d'imagerie devant une douleur lombaire aiguë de l'adulte","q":"Quel est l'examen de référence pour le diagnostic d'une spondylodiscite ?","a":"<p>L'<strong>IRM</strong> (Imagerie par Résonance Magnétique) est l'examen de référence pour le diagnostic de la spondylodiscite.</p>"},{"i":"1278106de336","n":270,"o":"270-6","u":"Examens complémentaires","t":"Connaître le bilan biologique à prescrire en cas de douleur lombaire aiguë","q":"Pourquoi une analyse d'urine est-elle systématique en cas de douleur lombaire aiguë avec suspicion d'origine urologique et que recherche-t-on spécifiquement ?","a":"<p>Une analyse d'urine est systématique pour rechercher :</p><ul><li>Une <strong>leucocyturie</strong> qui oriente vers un <strong>ECBU</strong> à la recherche d'une infection urinaire.</li><li>Une <strong>hématurie</strong> qui est très en faveur d'une <strong>colique néphrétique</strong> ; son absence permet quasiment d'écarter ce diagnostic.</li></ul>"},{"i":"51c7ba8354f4","n":270,"o":"270-6","u":"Examens complémentaires","t":"Connaître le bilan biologique à prescrire en cas de douleur lombaire aiguë","q":"Dans quel contexte clinique la réalisation d'un bilan biologique est-elle indiquée en cas de douleur lombaire aiguë ?","a":"<p>Un bilan biologique de débrouillage est indiqué en cas de douleur lombaire aiguë lorsque l'on suspecte une <strong>cause urologique</strong> ou un <strong>retentissement systémique</strong> de la pathologie.</p>"},{"i":"c763cb9e938d","n":270,"o":"270-6","u":"Examens complémentaires","t":"Connaître le bilan biologique à prescrire en cas de douleur lombaire aiguë","q":"Quels sont les examens biologiques systématiques à prescrire en cas de douleur lombaire aiguë justifiant un bilan sanguin ?","a":"<ul><li><strong>Numération Formule Sanguine (NFS)</strong></li><li><strong>Protéine C Réactive (CRP)</strong></li><li><strong>Ionogramme sanguin</strong></li><li><strong>Créatininémie</strong> (pour évaluer la fonction rénale, notamment avant une injection de produit de contraste)</li></ul>"}]};